<?php
/**
 * Cart rules: bundle pricing, free shipping 2+, one-page checkout, AJAX bag.
 */
defined( 'ABSPATH' ) || exit;

/** Is this product a Bunny Babe scent (counts towards bundles)? */
function bb_is_scent_product( $product ) {
	if ( ! $product instanceof WC_Product ) {
		return false;
	}
	$id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	return has_term( bb_config()['category'], 'product_cat', $id );
}

/** Bottles of scent in a list of cart items. */
function bb_count_scents( $items ) {
	$n = 0;
	foreach ( (array) $items as $item ) {
		if ( ! empty( $item['data'] ) && bb_is_scent_product( $item['data'] ) ) {
			$n += (int) $item['quantity'];
		}
	}
	return $n;
}

function bb_cart_scent_count() {
	return ( WC()->cart ) ? bb_count_scents( WC()->cart->get_cart() ) : 0;
}

/* ------------------------------------------------------------------
 * Bundle pricing: 2 = RM35.50, 5 = RM85.50, mixed scents, best combo.
 * Applied as a negative fee "Bundle savings".
 * ------------------------------------------------------------------ */
add_action(
	'woocommerce_cart_calculate_fees',
	function ( $cart ) {
		if ( is_admin() && ! wp_doing_ajax() ) {
			return;
		}
		$n      = 0;
		$normal = 0.0;
		foreach ( $cart->get_cart() as $item ) {
			if ( bb_is_scent_product( $item['data'] ) ) {
				$n      += (int) $item['quantity'];
				$normal += (float) $item['data']->get_price() * (int) $item['quantity'];
			}
		}
		if ( $n < 2 ) {
			return;
		}
		$save = round( $normal - bb_bundle_price( $n ), 2 );
		if ( $save > 0.004 ) {
			$cart->add_fee( __( 'Bundle savings', 'bunnybabe' ), -$save, false );
		}
	}
);

/* ------------------------------------------------------------------
 * Shipping: flat rate (RM6, set in the Malaysia zone) becomes FREE
 * from 2 bottles.
 * ------------------------------------------------------------------ */
add_filter(
	'woocommerce_package_rates',
	function ( $rates, $package ) {
		$n = bb_count_scents( isset( $package['contents'] ) ? $package['contents'] : array() );
		if ( $n < (int) bb_config()['free_ship_min'] ) {
			return $rates;
		}
		foreach ( $rates as $rate ) {
			if ( 'flat_rate' === $rate->get_method_id() ) {
				$rate->set_cost( 0 );
				$taxes = $rate->get_taxes();
				$rate->set_taxes( is_array( $taxes ) ? array_map( '__return_zero', $taxes ) : array() );
				$rate->set_label( __( 'FREE shipping', 'bunnybabe' ) );
			}
		}
		return $rates;
	},
	20,
	2
);

/* ------------------------------------------------------------------
 * One-page checkout on the front page.
 * ------------------------------------------------------------------ */

// Load checkout scripts on the front page.
add_filter(
	'woocommerce_is_checkout',
	function ( $is ) {
		if ( $is || is_admin() || ! did_action( 'wp' ) ) {
			return $is;
		}
		return is_front_page();
	}
);

// Show the checkout form on the front page even when the bag is empty
// (it is hidden by CSS until something is added).
add_filter(
	'woocommerce_checkout_redirect_empty_cart',
	function ( $redirect ) {
		return ( did_action( 'wp' ) && is_front_page() ) ? false : $redirect;
	}
);

// Don't swap the checkout form for "session expired" while the bag is empty —
// the one-page layout hides the form until something is added.
add_filter( 'woocommerce_checkout_update_order_review_expired', '__return_false' );

// We have our own voucher box in the bag.
add_action(
	'init',
	function () {
		remove_action( 'woocommerce_before_checkout_form', 'woocommerce_checkout_coupon_form', 10 );
		remove_action( 'woocommerce_before_checkout_form', 'woocommerce_checkout_login_form', 10 );
	}
);

add_filter( 'woocommerce_enable_order_notes_field', '__return_false' );
add_filter( 'woocommerce_cart_needs_shipping_address', '__return_false' );

// Simpler checkout fields.
add_filter(
	'woocommerce_checkout_fields',
	function ( $fields ) {
		foreach ( array( 'billing_company', 'billing_address_2', 'billing_last_name' ) as $key ) {
			unset( $fields['billing'][ $key ] );
		}
		$labels = array(
			'billing_phone'      => array( __( 'WhatsApp number', 'bunnybabe' ), 5, array( 'form-row-wide' ) ),
			'billing_first_name' => array( __( 'Full name', 'bunnybabe' ), 10, array( 'form-row-wide' ) ),
			'billing_email'      => array( __( 'Email for your receipt', 'bunnybabe' ), 90, array( 'form-row-wide' ) ),
			'billing_country'    => array( __( 'Country', 'bunnybabe' ), 40, array( 'form-row-wide' ) ),
			'billing_address_1'  => array( __( 'Address', 'bunnybabe' ), 50, array( 'form-row-wide' ) ),
			'billing_postcode'   => array( __( 'Postcode', 'bunnybabe' ), 60, array( 'form-row-first' ) ),
			'billing_city'       => array( __( 'City', 'bunnybabe' ), 70, array( 'form-row-last' ) ),
			'billing_state'      => array( __( 'State', 'bunnybabe' ), 80, array( 'form-row-wide' ) ),
		);
		foreach ( $labels as $key => $l ) {
			if ( isset( $fields['billing'][ $key ] ) ) {
				$fields['billing'][ $key ]['label']    = $l[0];
				$fields['billing'][ $key ]['priority'] = $l[1];
				$fields['billing'][ $key ]['class']    = $l[2];
			}
		}
		if ( isset( $fields['billing']['billing_phone'] ) ) {
			$fields['billing']['billing_phone']['required']    = true;
			$fields['billing']['billing_phone']['placeholder'] = '012-345 6789';
		}
		if ( isset( $fields['billing']['billing_email'] ) ) {
			$fields['billing']['billing_email']['required'] = false;
		}
		if ( isset( $fields['billing']['billing_address_1'] ) ) {
			$fields['billing']['billing_address_1']['placeholder'] = __( 'House no., street, area', 'bunnybabe' );
		}
		return $fields;
	},
	20
);

// Address labels/order live here too (WooCommerce re-applies these per country).
add_filter(
	'woocommerce_default_address_fields',
	function ( $f ) {
		$map = array(
			'country'   => array( __( 'Country', 'bunnybabe' ), 40 ),
			'address_1' => array( __( 'Address', 'bunnybabe' ), 50 ),
			'postcode'  => array( __( 'Postcode', 'bunnybabe' ), 60 ),
			'city'      => array( __( 'City', 'bunnybabe' ), 70 ),
			'state'     => array( __( 'State', 'bunnybabe' ), 80 ),
		);
		foreach ( $map as $key => $m ) {
			if ( isset( $f[ $key ] ) ) {
				$f[ $key ]['label']    = $m[0];
				$f[ $key ]['priority'] = $m[1];
			}
		}
		if ( isset( $f['address_1'] ) ) {
			$f['address_1']['placeholder'] = __( 'House no., street, area', 'bunnybabe' );
		}
		return $f;
	},
	20
);

// WhatsApp number is always required (vouchers + tracking use it).
add_filter(
	'pre_option_woocommerce_checkout_phone_field',
	function () {
		return 'required';
	}
);

add_filter(
	'woocommerce_order_button_text',
	function () {
		return __( 'Place order', 'bunnybabe' );
	}
);

// Cart page, shop and product categories all go to the one page.
add_action(
	'template_redirect',
	function () {
		if ( is_admin() || wp_doing_ajax() ) {
			return;
		}
		if ( function_exists( 'is_cart' ) && is_cart() ) {
			wp_safe_redirect( home_url( '/#checkout' ) );
			exit;
		}
		if ( ( function_exists( 'is_shop' ) && is_shop() ) || ( function_exists( 'is_product_category' ) && is_product_category() ) ) {
			wp_safe_redirect( home_url( '/#scents' ) );
			exit;
		}
	}
);

/* ------------------------------------------------------------------
 * AJAX bag.
 * ------------------------------------------------------------------ */

/** Render the bag items list. */
function bb_render_bag_items() {
	if ( ! WC()->cart ) {
		return;
	}
	foreach ( WC()->cart->get_cart() as $key => $item ) {
		$product = $item['data'];
		if ( ! $product ) {
			continue;
		}
		$pid   = (int) $item['product_id'];
		$scent = bb_scent_key_for_product( $pid );
		$img   = $scent ? bb_asset( 'img/' . bb_config()['scents'][ $scent ]['bottle'] ) : wp_get_attachment_image_url( $product->get_image_id(), 'thumbnail' );
		$name  = $scent ? bb_config()['scents'][ $scent ]['name'] : $product->get_name();
		$qty   = (int) $item['quantity'];
		?>
		<div class="bb-bag__item">
			<?php if ( $img ) : ?>
				<img src="<?php echo esc_url( $img ); ?>" alt="" width="60" height="60" loading="lazy">
			<?php endif; ?>
			<div class="bb-bag__meta">
				<strong><?php echo esc_html( $name ); ?></strong>
				<span><?php esc_html_e( '30ml Eau de Parfum', 'bunnybabe' ); ?></span>
			</div>
			<div class="bb-stepper">
				<button type="button" data-bb-set="<?php echo esc_attr( $pid ); ?>" data-qty="<?php echo esc_attr( $qty - 1 ); ?>" aria-label="<?php echo esc_attr( sprintf( /* translators: %s scent */ __( 'Remove one %s', 'bunnybabe' ), $name ) ); ?>">−</button>
				<span><?php echo esc_html( $qty ); ?></span>
				<button type="button" data-bb-set="<?php echo esc_attr( $pid ); ?>" data-qty="<?php echo esc_attr( $qty + 1 ); ?>" aria-label="<?php echo esc_attr( sprintf( /* translators: %s scent */ __( 'Add one %s', 'bunnybabe' ), $name ) ); ?>">+</button>
			</div>
		</div>
		<?php
	}
}

/** Everything the page needs to redraw the bag. */
function bb_bag_state() {
	$cart = WC()->cart;
	$cart->calculate_totals();
	$n    = bb_count_scents( $cart->get_cart() );
	$qtys = array();
	foreach ( $cart->get_cart() as $item ) {
		$pid          = (int) $item['product_id'];
		$qtys[ $pid ] = ( isset( $qtys[ $pid ] ) ? $qtys[ $pid ] : 0 ) + (int) $item['quantity'];
	}
	ob_start();
	bb_render_bag_items();
	$items_html = ob_get_clean();

	// What the customer saves: bundle + vouchers + free shipping.
	$bundle_save = 0.0;
	foreach ( $cart->get_fees() as $fee ) {
		if ( isset( $fee->amount ) && $fee->amount < 0 ) {
			$bundle_save += -1 * (float) $fee->amount;
		}
	}
	$free_ship  = $n >= (int) bb_config()['free_ship_min'];
	$ship_saved = ( $free_ship && $n > 0 ) ? (float) bb_config()['ship_fee'] : 0.0;
	$saving     = round( $bundle_save + (float) $cart->get_discount_total() + $ship_saved, 2 );
	$saving_amt = $saving > 0.004 ? html_entity_decode( wp_strip_all_tags( wc_price( $saving ) ), ENT_QUOTES, 'UTF-8' ) : '';

	return array(
		'saving_amt' => $saving_amt,
		'free_ship'  => $free_ship,
		'count'      => (int) $cart->get_cart_contents_count(),
		'scents'     => $n,
		'qtys'       => $qtys,
		'empty'      => $cart->is_empty(),
		'items_html' => $items_html,
		'total_html' => $cart->get_total(),
		'tier_msg'   => bb_tier_message( $n ),
		'tier_pct'   => bb_tier_percent( $n ),
		'ship_nudge' => $n > 0 && $n < (int) bb_config()['free_ship_min'],
		'coupons'    => array_values( $cart->get_applied_coupons() ),
		'notices'    => wc_print_notices( true ),
	);
}

function bb_ajax_bag() {
	if ( ! WC()->cart ) {
		wp_send_json_error( array( 'message' => 'Cart unavailable' ) );
	}
	// phpcs:disable WordPress.Security.NonceVerification.Missing -- cart actions, same as WooCommerce's own add-to-cart AJAX.
	$op  = isset( $_POST['op'] ) ? sanitize_key( wp_unslash( $_POST['op'] ) ) : 'state';
	$pid = isset( $_POST['product'] ) ? absint( $_POST['product'] ) : 0;
	$qty = isset( $_POST['qty'] ) ? (int) $_POST['qty'] : 0;
	$code = isset( $_POST['code'] ) ? wc_format_coupon_code( sanitize_text_field( wp_unslash( $_POST['code'] ) ) ) : '';
	// phpcs:enable

	$cart = WC()->cart;

	switch ( $op ) {
		case 'add':
			if ( $pid ) {
				$cart->add_to_cart( $pid, max( 1, min( 20, $qty ? $qty : 1 ) ) );
			}
			break;

		case 'addall':
			foreach ( array_keys( bb_config()['scents'] ) as $key ) {
				$id = bb_scent_product_id( $key );
				if ( $id ) {
					$cart->add_to_cart( $id, 1 );
				}
			}
			break;

		case 'set':
			$found = false;
			foreach ( $cart->get_cart() as $key => $item ) {
				if ( (int) $item['product_id'] === $pid ) {
					$cart->set_quantity( $key, max( 0, min( 50, $qty ) ) );
					$found = true;
					break;
				}
			}
			if ( ! $found && $qty > 0 && $pid ) {
				$cart->add_to_cart( $pid, min( 50, $qty ) );
			}
			break;

		case 'coupon':
			if ( $code ) {
				$cart->apply_coupon( $code );
			}
			break;

		case 'uncoupon':
			if ( $code ) {
				$cart->remove_coupon( $code );
			}
			break;
	}

	if ( function_exists( 'bb_maybe_apply_pending_coupon' ) ) {
		bb_maybe_apply_pending_coupon();
	}

	wp_send_json_success( bb_bag_state() );
}
add_action( 'wp_ajax_bb_bag', 'bb_ajax_bag' );
add_action( 'wp_ajax_nopriv_bb_bag', 'bb_ajax_bag' );


